def main() -> None:
    threats_by_case = {
        case_dir.name: json.loads(
            (case_dir / "claims" / "stride.json").read_text()
        )
        for case_dir in sorted(CORPUS.iterdir())
        if case_dir.is_dir()
    }
    pairs = []
    for case, index, candidate, label, note, elements in LABELS:
        reference = threats_by_case[case][index]
        pairs.append(
            {
                "case": case,
                "category": reference["category"],
                "reference_claim": reference["claim"],
                # Free: the corpus already holds it, so no hand pass assigns it
                # and no reworded reference can detach it from its claim.
                "reference_element_ids": sorted(reference["affected_element_ids"]),
                "candidate_claim": candidate,
                "candidate_element_ids": None if elements is None else list(elements),
                "label": label,
                "note": note,
            }
        )

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(pairs, indent=2) + "\n")
    matches = sum(1 for pair in pairs if pair["label"] == "match")
    elemented = sum(1 for pair in pairs if pair["candidate_element_ids"] is not None)
    print(f"{len(pairs)} pairs: {matches} match, {len(pairs) - matches} no-match")
    print(f"{elemented} carry candidate element IDs")


if __name__ == "__main__":
    main()
